code_examples:
// v1.1.9 的正确写法：v/a 不画箭头，只声明刚体
VIEW: `
  SIM = { duration: 2, bodies: [{ id: 'block', at: (s) => [s.x, 0.15] }] };
`
setup: `
  const v0 = 2;
  RETURN('v0', v0);
`
stateAt: `
  const v0 = context.v0;
  return { x: -v0 * t, v: -v0 };            // 向左运动 ⇒ 速度与位移都为负
`
drawFrame: `
  const p = [state.x, 0.15];
  Draw.ground(-2.4, 0.6);
  Draw.box(p, 0.4, 0.3);
  // v 箭头由 bodies 自动生成（绿色、朝左），这里不用写
`

drawFrame: `
  // 两个阶段边界：细虚线标出，不写文字
  Draw.line([0, -0.2], [0, 2.2], { dash: true });
  Draw.line([1, -0.2], [1, 2.2], { dash: true });
`

// 三个最常用元件的最小画法（完整清单见正文）
stateAt: `
  return { x: 0.6, yTop: 1.6 };
`
drawFrame: `
  Draw.incline([0, 0.6], { angleDeg: 30, length: 1.2 });
  Draw.box([state.x, 0.15], 0.4, 0.3);
  Draw.spring([0, 2.0], [0, state.yTop], { coils: 12 });
`
